def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * (3 * w) for _ in range(3 * h)]

    # Each occupied input cell becomes a 3x3 tile containing the
    # complement of the input's occupied-cell pattern.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                for dr in range(3):
                    for dc in range(3):
                        if grid[dr][dc] == 0:
                            out[3 * r + dr][3 * c + dc] = grid[r][c]
    return out
